insert into programs (id,name,country,cc,levels,funding,base_adm,base_sch,req,deadline,deadline_md,apply_open_md,note,fields,lang_year,source_url,available_kz,verified) values ('tr_uni_merit','Полные merit-стипендии частных вузов Турции (Koç, Sabancı, Bilkent)','Турция','tr',array['bachelor','master']::text[],'до 100% платы + у части вузов стипендия и общежитие',0.3,0.3,'{"academics": 7.5, "language": 6, "budget": 0}'::jsonb,'апрель–май','04-30','01-01','merit решается вместе с зачислением; сильный аттестат и олимпиады решают',null,false,'https://apply.ku.edu.tr/',true,false) on conflict (id) do update set base_adm=excluded.base_adm, base_sch=excluded.base_sch, req=excluded.req, deadline_md=excluded.deadline_md, apply_open_md=excluded.apply_open_md, updated_at=now();
